// src/domains/media/media-categories.ts
/** The kinds a MIME type's first part names: `image/png` is an image. */
const MEDIA_TYPE_PREFIXES = {
	image: "image/",
	video: "video/",
	audio: "audio/"
};
/**
* What makes a file a document: a PDF, an office file (Word's own type and
* the vendor `application/vnd.` types) and any text. What no kind names is
* `other`.
*/
const DOCUMENT_MIME_TYPES = {
	exact: ["application/pdf"],
	prefixes: [
		"application/vnd.",
		"application/msword",
		"text/"
	]
};
/** The kind of file a MIME type is; a missing or blank one is `other`. */
function mediaCategoryOf(mimeType) {
	if (!mimeType || mimeType.trim() === "") return "other";
	for (const [category, prefix] of Object.entries(MEDIA_TYPE_PREFIXES)) if (mimeType.startsWith(prefix)) return category;
	if (DOCUMENT_MIME_TYPES.exact.includes(mimeType) || DOCUMENT_MIME_TYPES.prefixes.some((prefix) => mimeType.startsWith(prefix))) return "document";
	return "other";
}
export { DOCUMENT_MIME_TYPES, MEDIA_TYPE_PREFIXES, mediaCategoryOf };
